using System;
using System.Linq;
namespace IdleIntelligence.Core
{
    public static class MaterialAnalysis
    {
        public static bool Access(GameState s,int family)=>family==0||family==1&&Game.Level(s,"blueprints")>0||family==2&&Game.Level(s,"materialAnalysis")>=3||family==3&&Game.Level(s,"blueprintAnalysis")>=5||family==4&&Game.Level(s,"materialAnalysis")>=10;
        public static int Family(int component)=>Array.FindIndex(ItemBalance.MaterialFamilies,ids=>ids.Contains(ItemBalance.ComponentIds[component]));
        public static string Block(GameState s,int n)
        {
            if(n<0||n>=ItemBalance.Analyses.Length)return "Unbekannt";string type=ItemBalance.Analyses[n].Id.Split('-')[0];return s.Workshop.hasAnalysis||s.Industry.synthesis!=null?"Analyse läuft":type=="architecture"&&Game.Level(s,"blueprints")==0?"Forschung: Baupläne":type=="artifact"&&Game.Level(s,"blueprintAnalysis")<3?"Bauplananalyse Lv. 3":s.Data.CompareTo(ScientificNumber.From(Industry.AnalysisCost(s,ItemBalance.Analyses[n].Cost)))<0?"Zu wenig Daten":null;
        }
        public static int RareCandidate(GameState s)
        {bool Allowed(int c)=>ItemBalance.RareComponents[c]&&Access(s,Family(c));int old=Array.IndexOf(ItemBalance.ComponentIds,"graphene");if(Allowed(old))return old;for(int c=0;c<ItemBalance.ComponentIds.Length;c++)if(Allowed(c))return c;return -1;}
        public static void ValidateFamilyContract(GameState s)
        {var job=s.Workshop.analysis;if(job==null||job.familyContractVersion==0)return;if(job.familyContractVersion!=1||!ItemSystemV3.Enabled(s)||job.familyFactors==null||job.familyFactors.Length!=5||job.familyFactors.Any(v=>!ScientificNumber.Finite(v)||v<1||v>ItemSystemV3.MaximumFamilyYield()+1e-10)||job.rareComponent < -1||job.rareComponent>=ItemBalance.ComponentIds.Length||job.rareComponent>=0&&!ItemBalance.RareComponents[job.rareComponent])throw new FormatException("Invalid analysis family contract");}
        public static bool RepeatUnlocked(GameState s)=>PrestigeRules.Has(s,"F03")||MetaRules.Level(s,"C02")>0;
        public static bool RecipeAccess(GameState s,int n)=>n>=0&&n<ItemBalance.Analyses.Length&&(!ItemBalance.Analyses[n].Id.StartsWith("architecture")||Game.Level(s,"blueprints")>0)&&(!ItemBalance.Analyses[n].Id.StartsWith("artifact")||Game.Level(s,"blueprintAnalysis")>=3);
        public static GameState Queue(GameState state,int n){if(state.Prestige.resetIntent||!PrestigeRules.Has(state,"F02")||!RecipeAccess(state,n)||state.Industry.analysisQueue.Length>=IndustryBalance.AnalysisQueueCapacity)return state;var s=state.Copy();s.Industry.analysisQueue=s.Industry.analysisQueue.Concat(new[]{n}).ToArray();s.Workshop.revision++;return s;}
        public static GameState RemoveQueued(GameState state,int index){if(index<0||index>=state.Industry.analysisQueue.Length)return state;var s=state.Copy();s.Industry.analysisQueue=s.Industry.analysisQueue.Where((n,i)=>i!=index).ToArray();s.Workshop.revision++;return s;}
        public static GameState StartQueued(GameState state){if(state.Prestige.resetIntent||state.Industry.analysisQueue.Length==0||state.Workshop.hasAnalysis||state.Industry.synthesis!=null)return state;var next=Start(state,state.Industry.analysisQueue[0]);if(ReferenceEquals(next,state))return state;next.Industry.analysisQueue=next.Industry.analysisQueue.Skip(1).ToArray();return next;}
        public static GameState ToggleRepeat(GameState state){if(!RepeatUnlocked(state))return state;var s=state.Copy();s.Meta.analysisAuto=!s.Meta.analysisAuto;s.Meta.analysisSeconds=0;s.Workshop.revision++;return s;}
        public static double Units(GameState s,int n)=>PrestigeV3.MaterialYield(s)*ItemSystemV3.AnalysisCombinationYield(s)*(ItemSystemV3.Enabled(s)&&MetaRules.Secondary(s,"K10")?PrestigeRules.E("D06quantity"):1)*ItemBalance.Analyses[n].Units*(1+ItemBalance.MaterialAnalysisEffect*Game.Level(s,"materialAnalysis"))*(s.Workshop.focus>=0&&Access(s,s.Workshop.focus)?ItemSystemV3.FocusQuantity(s):1);
        public static double BaseSpeed(GameState s)=>(1+Workshop.Bonus(s,"experiment"))*(1+ItemBalance.LabAutomationEffect*Game.Level(s,"labAutomation"))*MetaRules.Factor(s,"analysis")*(MetaRules.Secondary(s,"K05")?PrestigeRules.E("D06speed"):1);
        public static double Speed(GameState s)=>BaseSpeed(s)*ItemSystemV3.AnalysisFactor(s).ToDouble();
        public static GameState Start(GameState state,int n)
        {
            var selected=MetaRules.Phase(state,2);if(Block(selected,n)!=null)return state;var s=selected.Copy();var w=s.Workshop;var d=ItemBalance.Analyses[n];string type=d.Id.Split('-')[0];int max=type=="hardware"?2:type=="architecture"?3:5;var weights=new double[w.components.Length];
            bool focus=w.focus>=0&&Access(s,w.focus);for(int c=0;c<weights.Length;c++){int family=Family(c);weights[c]=family<max&&Access(s,family)?(focus&&family==w.focus?ItemBalance.MaterialFocusWeight*(ItemSystemV3.Enabled(s)?ItemSystemV3.FocusFactor(s):1+Workshop.Device(s,"focus")):1):0;}
            s.Data=s.Data.Subtract(ScientificNumber.From(Industry.AnalysisCost(s,d.Cost)));w.nextId++;w.hasAnalysis=true;w.analysis=new AnalysisJob{key="exp-"+(w.nextId-1),startedAt=s.SavedAt,startRecorded=true,rareGuarantee=PrestigeRules.Has(s,"W03"),familyContractVersion=ItemSystemV3.Enabled(s)?1:0,rareComponent=ItemSystemV3.Enabled(s)?RareCandidate(s):-1,familyFactors=ItemSystemV3.Enabled(s)?Enumerable.Range(0,5).Select(f=>(focus&&f==w.focus&&PrestigeRules.Has(s,"W03")?ItemV3Balance.Get("prestige.items.W03focus"):1d)*ItemSystemV3.MaterialFamilyYield(s,f)).ToArray():null,definition=n,required=d.Work,units=d.Units*(1+ItemBalance.MaterialAnalysisEffect*Game.Level(s,"materialAnalysis"))*(focus?ItemSystemV3.FocusQuantity(s):1),blueprints=d.Fragments*(1+.1*Game.Level(s,"blueprintAnalysis")),weights=weights,order=ItemBalance.MaterialFamilies.Take(max).SelectMany(ids=>ids).Select(id=>Array.IndexOf(ItemBalance.ComponentIds,id)).Where(c=>weights[c]>0).ToArray(),combination=Workshop.Combination(s,"material-mapping")*PrestigeV3.MaterialYield(s)*ItemSystemV3.AnalysisCombinationYield(s)*(ItemSystemV3.Enabled(s)&&MetaRules.Secondary(s,"K10")?PrestigeRules.E("D06quantity"):1)};w.revision++;LocalJournal.Record(s,"experiment-start",d.Id,dataCost:ScientificNumber.From(Industry.AnalysisCost(selected,d.Cost)));return s;
        }
        public static GameState Cancel(GameState state){if(!state.Workshop.hasAnalysis)return state;var s=state.Copy();s.Workshop.hasAnalysis=false;s.Workshop.analysis=null;s.Workshop.revision++;LocalJournal.Record(s,"experiment-cancel",permanent:false);return s;}
        static double Draw(WorkshopState w){w.materialRng=unchecked(w.materialRng*1664525u+1013904223u);return w.materialRng/4294967296d;}
        static long Split(double value,out double remainder)
        {double near=Math.Floor(value+.5);if(Math.Abs(value-near)<=2.220446049250313e-16*Math.Max(1,Math.Abs(value))*16)value=near;long whole=(long)Math.Floor(value);remainder=value-whole;return whole;}
        public static void Advance(GameState s,double seconds,bool finish=true)
        {
            var w=s.Workshop;if(!w.hasAnalysis)return;ValidateFamilyContract(s);var job=w.analysis;double delta=Math.Min(job.required-job.done,Speed(s)*seconds);job.done+=delta;double quantity=MetaRules.Secondary(s,"K10")?PrestigeRules.E("D06quantity"):1;job.quantityIntegral+=delta*quantity;job.photonicIntegral+=delta*quantity*(1+Workshop.Device(s,"photonicYield"));job.quantumIntegral+=delta*quantity*(1+Workshop.Device(s,"quantumYield"));if(!finish||job.done+1e-7<job.required)return;
            var definition=ItemBalance.Analyses[job.definition];long count=Split(job.units+w.componentRemainder,out w.componentRemainder);var found=new long[w.components.Length];double total=job.weights.Sum();
            for(long i=0;i<count;i++){double roll=Draw(w);int picked=job.order.Last();foreach(int c in job.order){roll-=job.weights[c]/total;if(roll<=0){picked=c;break;}}found[picked]++;}
            int rare=job.familyContractVersion==1?job.rareComponent:5;if(job.rareGuarantee&&rare>=0&&!Enumerable.Range(0,found.Length).Any(c=>found[c]>0&&ItemBalance.RareComponents[c]))found[rare]++;
            var before=(long[])w.components.Clone();for(int c=0;c<found.Length;c++){int family=Family(c);double v=found[c]*job.combination*(job.familyContractVersion==1?job.familyFactors[family]:family==2?job.photonicIntegral/job.required:family==4?job.quantumIntegral/job.required:job.quantityIntegral/job.required)+w.analysisRemainders[c];long amount=Split(v,out w.analysisRemainders[c]);w.components[c]+=amount;Lifetime.Components(s,c,amount,"analysis");}
            long fragments=Split(job.blueprints+w.blueprintRemainder,out w.blueprintRemainder);w.fragments+=fragments;if(s.AdvanceLog!=null)s.AdvanceLog.Fragments+=fragments;double research=definition.Id.StartsWith("architecture")?definition.Fragments:0;long researchFragments=Split(research+w.researchRemainder,out w.researchRemainder);w.researchFragments+=researchFragments;if(s.AdvanceLog!=null)s.AdvanceLog.ResearchFragments+=researchFragments;
            if(!ChallengeRules.Is(s,"closed-supply-chain")&&definition.ItemChance>0&&Draw(w)<definition.ItemChance){var candidates=ItemBalance.Items.Where(i=>i.Id!="impulse-relay"&&i.Id!="insight-archive").ToArray();var item=new ItemInstance{missingMaterialBasis=true,id="item-"+w.nextId++,type=candidates[(int)Math.Floor(Draw(w)*candidates.Length)].Id};w.inventory=w.inventory.Concat(new[]{item}).ToArray();Lifetime.Item(s,item.type);LocalJournal.Record(s,"item-create",item.id);}
            if(ItemSystemV3.Enabled(s)&&ItemSystemV3.Has(s,"field-scanner")){if(s.ItemSystemV3.scannerAnalyses>=9007199254740991L)throw new FormatException("Invalid scanner analysis receipt");s.ItemSystemV3.scannerAnalyses++;}
            ItemSystemV3.CompletePaidAnalysis(s,definition.Id,job.key);s.Industry.lastAnalysisRecipe=job.definition;s.Industry.lastAnalysisAmounts=found.Select((v,c)=>s.Workshop.components[c]-before[c]).ToArray();s.Industry.firstAnalysisReward=true;s.Lifetime.analysesCompleted++;w.hasAnalysis=false;w.revision++;LocalJournal.Record(s,"component-found",definition.Id);LocalJournal.Record(s,"experiment-complete",definition.Id,duration:w.analysis.startRecorded?(s.SavedAt-w.analysis.startedAt)/1000:-1);w.analysis=null;
        }
    }
}
